import Foundation

/// Decides whether a clipboard change may be recorded.
public struct CapturePolicy {
    /// Markers apps add to sensitive or throwaway pasteboard contents
    /// (see nspasteboard.org); password managers set these on copied passwords.
    public static let confidentialTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    /// Captures larger than this are skipped to keep memory and disk use sane.
    public static let maxPayloadBytes = 64 * 1024 * 1024

    public let ignoreConfidential: Bool
    public let ignoredBundleIDs: Set<String>

    public init(ignoreConfidential: Bool, ignoredBundleIDs: Set<String>) {
        self.ignoreConfidential = ignoreConfidential
        self.ignoredBundleIDs = ignoredBundleIDs
    }

    /// - Parameters:
    ///   - types: every type on the pasteboard.
    ///   - sourceBundleID: the frontmost app when the copy happened.
    public func allowsCapture(types: Set<String>, sourceBundleID: String?) -> Bool {
        if types.isEmpty { return false }
        if let bundleID = sourceBundleID, ignoredBundleIDs.contains(bundleID) { return false }
        if ignoreConfidential && !types.isDisjoint(with: Self.confidentialTypes) { return false }
        return true
    }
}
